'use strict';

// MODULES //

var rfftf1 = require( './rfftf1.js' );


// MAIN //

/**
* Performs the forward FFT for real-valued sequences.
*
* @param {number} n - length of the sequence to transform
* @param {Float64Array} r - array containing sequence to be transformed
* @param {Float64Array} wsave - working array containing precomputed values
* @returns {void}
*/
function rfftf( n, r, wsave ) {
	if ( n === 1 ) {
		return;
	}
	rfftf1( n, r[ 1 - 1 ], wsave[ 1 - 1 ], wsave[ n + 1 - 1 ], wsave[ ( n << 1 ) + 1 - 1 ] ); // eslint-disable-line max-len
}


// EXPORTS //

module.exports = rfftf;
